UPDATE (Списки_агрегатов LEFT JOIN Турбины ON (Списки_агрегатов.stcode=Турбины.numb1120) AND (Списки_агрегатов.stnumb=Турбины.stnumb)) LEFT JOIN Тепловые_мощности ON Списки_агрегатов.name=Тепловые_мощности.typename SET Списки_агрегатов.nt = IIf(Списки_агрегатов!year<2000,Турбины!nt,IIf(Турбины!opesname=Списки_агрегатов!name,Турбины!nt,Тепловые_мощности!nt));
